From 18c03c4668550e924f43c2bfe3959535ff7a1a5e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:29:30 +0100
Subject: [PATCH] libkworkspace: notify the user when a session or power action
 fails

When a logout, shutdown, restart, sleep, lock or user switch failed,
the D-Bus error was dropped and clicking the button did nothing at
all. Now the error is shown in a notification named after the action.

BUG: 500867
---
 libkworkspace/sessionmanagement.cpp        | 34 +++++++++++------
 libkworkspace/sessionmanagementbackend.cpp | 44 ++++++++++++++++++++--
 libkworkspace/sessionmanagementbackend.h   |  2 +
 3 files changed, 64 insertions(+), 16 deletions(-)

diff --git a/libkworkspace/sessionmanagement.cpp b/libkworkspace/sessionmanagement.cpp
index 248147f505..8d8032c610 100644
--- a/libkworkspace/sessionmanagement.cpp
+++ b/libkworkspace/sessionmanagement.cpp
@@ -10,6 +10,7 @@

 #include <KAuthorized>
 #include <KConfigGroup>
+#include <KLocalizedString>
 #include <KSharedConfig>

 #include <QDBusPendingCallWatcher>
@@ -25,7 +26,7 @@

 using namespace Qt::StringLiterals;

-static void lockQuitUntilFinished(QDBusPendingCall pendingCall)
+static void lockQuitUntilFinished(QDBusPendingCall pendingCall, const QString &errorTitle)
 {
     auto watcher = new QDBusPendingCallWatcher(pendingCall);
     QEventLoopLocker eventLoopLocker;
@@ -35,8 +36,11 @@ static void lockQuitUntilFinished(QDBusPendingCall pendingCall)
     // If the recipient is dbus activated and the sender quits before the target is up
     // the method may not be dispatched.
     // See https://gitlab.freedesktop.org/dbus/dbus/-/issues/72
-    QObject::connect(watcher, &QDBusPendingCallWatcher::finished, watcher, [watcher, eventLoopLocker = std::move(eventLoopLocker)]() {
+    QObject::connect(watcher, &QDBusPendingCallWatcher::finished, watcher, [watcher, errorTitle, eventLoopLocker = std::move(eventLoopLocker)]() {
         watcher->deleteLater();
+        if (watcher->isError()) {
+            SessionBackend::notifyError(errorTitle, watcher->error().message());
+        }
     });
 }

@@ -158,7 +162,7 @@ void SessionManagement::requestLogoutPrompt()
         // not; if this function was invoked, it means they do want to see the logout
         // prompt right now
         LogoutPromptIface iface;
-        lockQuitUntilFinished(iface.promptAll());
+        lockQuitUntilFinished(iface.promptAll(), i18nc("@title:notification", "Could not show the logout screen"));
     }
 }

@@ -179,11 +183,11 @@ void SessionManagement::requestShutdown(ConfirmationMode confirmationMode)
     }
     if (confirm) {
         LogoutPromptIface iface;
-        lockQuitUntilFinished(iface.promptShutDown());
+        lockQuitUntilFinished(iface.promptShutDown(), i18nc("@title:notification", "Could not shut down"));

     } else {
         ShutdownIface iface;
-        lockQuitUntilFinished(iface.logoutAndShutdown());
+        lockQuitUntilFinished(iface.logoutAndShutdown(), i18nc("@title:notification", "Could not shut down"));
     }
 }

@@ -204,10 +208,10 @@ void SessionManagement::requestReboot(ConfirmationMode confirmationMode)
     }
     if (confirm) {
         LogoutPromptIface iface;
-        lockQuitUntilFinished(iface.promptReboot());
+        lockQuitUntilFinished(iface.promptReboot(), i18nc("@title:notification", "Could not restart"));
     } else {
         ShutdownIface iface;
-        lockQuitUntilFinished(iface.logoutAndReboot());
+        lockQuitUntilFinished(iface.logoutAndReboot(), i18nc("@title:notification", "Could not restart"));
     }
 }

@@ -222,10 +226,10 @@ void SessionManagement::requestLogout(ConfirmationMode confirmationMode)
     }
     if (confirm) {
         LogoutPromptIface iface;
-        lockQuitUntilFinished(iface.promptLogout());
+        lockQuitUntilFinished(iface.promptLogout(), i18nc("@title:notification", "Could not log out"));
     } else {
         ShutdownIface iface;
-        lockQuitUntilFinished(iface.logout());
+        lockQuitUntilFinished(iface.logout(), i18nc("@title:notification", "Could not log out"));
     }
 }

@@ -267,7 +271,7 @@ void SessionManagement::lock()
         return;
     }
     OrgFreedesktopScreenSaverInterface iface(QStringLiteral("org.freedesktop.ScreenSaver"), QStringLiteral("/ScreenSaver"), QDBusConnection::sessionBus());
-    iface.Lock();
+    lockQuitUntilFinished(iface.Lock(), i18nc("@title:notification", "Could not lock the screen"));
 }

 void SessionManagement::switchUser()
@@ -292,7 +296,7 @@ void SessionManagement::switchUser()
     connect(watcher, &QDBusPendingCallWatcher::finished, watcher, &QObject::deleteLater);
     connect(watcher, &QDBusPendingCallWatcher::finished, this, [](QDBusPendingCallWatcher *watcher) {
         if (watcher->isError()) {
-            qCWarning(LIBKWORKSPACE_DEBUG) << "Failed to lock screen before switching user:" << watcher->error().message();
+            SessionBackend::notifyError(i18nc("@title:notification", "Could not switch user"), watcher->error().message());
             return;
         }
         QDBusMessage switchToGreeterMessage = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.DisplayManager"),
@@ -300,7 +304,13 @@ void SessionManagement::switchUser()
                                                                              QStringLiteral("org.freedesktop.DisplayManager.Seat"),
                                                                              u"SwitchToGreeter"_s);

-        QDBusConnection::systemBus().asyncCall(switchToGreeterMessage);
+        auto switchWatcher = new QDBusPendingCallWatcher(QDBusConnection::systemBus().asyncCall(switchToGreeterMessage));
+        QObject::connect(switchWatcher, &QDBusPendingCallWatcher::finished, switchWatcher, [](QDBusPendingCallWatcher *switchWatcher) {
+            switchWatcher->deleteLater();
+            if (switchWatcher->isError()) {
+                SessionBackend::notifyError(i18nc("@title:notification", "Could not switch user"), switchWatcher->error().message());
+            }
+        });
     });
 }

diff --git a/libkworkspace/sessionmanagementbackend.cpp b/libkworkspace/sessionmanagementbackend.cpp
index d0742bfb9a..cb3ee25238 100644
--- a/libkworkspace/sessionmanagementbackend.cpp
+++ b/libkworkspace/sessionmanagementbackend.cpp
@@ -13,8 +13,10 @@
 #include <QDBusConnection>
 #include <QDBusConnectionInterface>
 #include <QDBusPendingCallWatcher>
+#include <QEventLoopLocker>

 #include <KConfigGroup>
+#include <KLocalizedString>
 #include <iostream>

 #include "login1_manager_interface.h"
@@ -56,6 +58,24 @@ bool SessionBackend::canSwitchUser() const
     return false;
 }

+void SessionBackend::notifyError(const QString &title, const QString &message)
+{
+    qWarning() << title << message;
+
+    QDBusMessage notify = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.Notifications"),
+                                                         QStringLiteral("/org/freedesktop/Notifications"),
+                                                         QStringLiteral("org.freedesktop.Notifications"),
+                                                         QStringLiteral("Notify"));
+    notify << i18nc("@title application name", "Session Management") << 0u << QStringLiteral("dialog-error") << title << message << QStringList()
+           << QVariantMap() << -1;
+
+    // Callers like the logout screen quit right after the failed action, so stay alive until the notification is sent
+    auto watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(notify));
+    QObject::connect(watcher, &QDBusPendingCallWatcher::finished, watcher, [watcher, eventLoopLocker = QEventLoopLocker()]() {
+        watcher->deleteLater();
+    });
+}
+
 DummySessionBackend::DummySessionBackend()
 {
     qCritical() << "Could not load a session backend. Session management operations such as shutdown will not be operational. This is a setup issue.";
@@ -189,22 +209,38 @@ void LogindSessionBackend::suspend()
 {
     // these need to be synchronous as well - ksmserver-logout-greeter specifically calls these
     // and will quit immediately after
-    m_login1->Suspend(true).waitForFinished();
+    auto reply = m_login1->Suspend(true);
+    reply.waitForFinished();
+    if (reply.isError()) {
+        notifyError(i18nc("@title:notification", "Could not sleep"), reply.error().message());
+    }
 }

 void LogindSessionBackend::hybridSuspend()
 {
-    m_login1->HybridSleep(true).waitForFinished();
+    auto reply = m_login1->HybridSleep(true);
+    reply.waitForFinished();
+    if (reply.isError()) {
+        notifyError(i18nc("@title:notification", "Could not sleep"), reply.error().message());
+    }
 }

 void LogindSessionBackend::hibernate()
 {
-    m_login1->Hibernate(true).waitForFinished();
+    auto reply = m_login1->Hibernate(true);
+    reply.waitForFinished();
+    if (reply.isError()) {
+        notifyError(i18nc("@title:notification", "Could not hibernate"), reply.error().message());
+    }
 }

 void LogindSessionBackend::suspendThenHibernate()
 {
-    m_login1->SuspendThenHibernate(true).waitForFinished();
+    auto reply = m_login1->SuspendThenHibernate(true);
+    reply.waitForFinished();
+    if (reply.isError()) {
+        notifyError(i18nc("@title:notification", "Could not sleep"), reply.error().message());
+    }
 }

 bool LogindSessionBackend::canShutdown() const
